+func TestFortinetCpeDetectionAndEnrichment(t *testing.T) {
+	const cveID = "CVE-2023-1234"
+	const cpeURI = "cpe:/o:fortinet:fortios:4.3.0"
+	advisories := []cvemodels.Fortinet{{
+		AdvisoryID:      "FG-IR-23-001",
+		AdvisoryURL:     "https://www.fortiguard.com/psirt/FG-IR-23-001",
+		Summary:         "FortiOS affected",
+		DetectionMethod: cvemodels.FortinetExactVersionMatch,
+	}, {
+		AdvisoryID:      "FG-IR-23-002",
+		AdvisoryURL:     "https://www.fortiguard.com/psirt/FG-IR-23-002",
+		Title:           "Another advisory",
+		DetectionMethod: cvemodels.FortinetVendorProductMatch,
+	}}
+	detail := cvemodels.CveDetail{CveID: cveID, Fortinets: advisories}
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		switch r.URL.Path {
+		case "/cpes":
+			_ = json.NewEncoder(w).Encode([]cvemodels.CveDetail{
+				detail,
+				{CveID: "CVE-2023-5678", Jvns: []cvemodels.Jvn{{JvnID: "JVN-001"}}},
+			})
+		case "/cves/" + cveID:
+			_ = json.NewEncoder(w).Encode(detail)
+		default:
+			http.NotFound(w, r)
+		}
+	}))
+	defer server.Close()
+
+	cnf := config.GoCveDictConf{VulnDict: config.VulnDict{Type: "http", URL: server.URL}}
+	result := models.ScanResult{ScannedCves: models.VulnInfos{}}
