+		t.Fatalf("detected %d CVEs, want Fortinet-only CVE", len(result.ScannedCves))
+	}
+	vuln := result.ScannedCves[cveID]
+	if !reflect.DeepEqual(vuln.Confidences, models.Confidences{models.FortinetExactVersionMatch}) {
+		t.Fatalf("confidence = %v", vuln.Confidences)
+	}
+	if len(vuln.DistroAdvisories) != 2 || vuln.DistroAdvisories[0].AdvisoryID != "FG-IR-23-001" || vuln.DistroAdvisories[1].AdvisoryID != "FG-IR-23-002" {
+		t.Fatalf("advisories = %v", vuln.DistroAdvisories)
+	}
+	if err := FillCvesWithNvdJvnFortinet(&result, cnf, logging.LogOpts{}); err != nil {
