+	}
+	contents := result.ScannedCves[cveID].CveContents[models.Fortinet]
+	if len(contents) != 2 || contents[0].SourceLink != advisories[0].AdvisoryURL || contents[1].Title != advisories[1].Title {
+		t.Fatalf("Fortinet contents = %v", contents)
+	}
+}
