+// ConvertFortinetToModel converts Fortinet advisories to CveContent.
+func ConvertFortinetToModel(cveID string, fortinets []cvedict.Fortinet) []CveContent {
+	contents := make([]CveContent, 0, len(fortinets))
+	for _, advisory := range fortinets {
+		cweIDs := make([]string, 0, len(advisory.Cwes))
+		for _, cwe := range advisory.Cwes {
+			cweIDs = append(cweIDs, cwe.CweID)
+		}
+		references := make(References, 0, len(advisory.References))
+		for _, ref := range advisory.References {
+			references = append(references, Reference{Link: ref.Link, Source: ref.Source})
+		}
+		contents = append(contents, CveContent{
+			Type:          Fortinet,
+			CveID:         cveID,
+			Title:         advisory.Title,
+			Summary:       advisory.Summary,
+			Cvss3Score:    advisory.Cvss3.BaseScore,
+			Cvss3Vector:   advisory.Cvss3.VectorString,
+			Cvss3Severity: advisory.Cvss3.BaseSeverity,
+			SourceLink:    advisory.AdvisoryURL,
+			CweIDs:        cweIDs,
+			References:    references,
+			Published:     advisory.PublishedDate,
+			LastModified:  advisory.LastModifiedDate,
+		})
+	}
+	return contents
+}
