+func TestFortinetPresentationOrder(t *testing.T) {
+	vuln := VulnInfo{CveID: "CVE-2023-1234", CveContents: CveContents{
+		Trivy:    {{Type: Trivy, Summary: "Trivy summary"}},
+		Fortinet: {{Type: Fortinet, Title: "Fortinet title", Summary: "Fortinet summary", SourceLink: "https://fortiguard.com/advisory", Cvss3Score: 8.8}},
+		Nvd:      {{Type: Nvd, Summary: "NVD summary", Cvss3Score: 7.5}},
+		GitHub:   {{Type: GitHub, Summary: "GitHub summary"}},
+	}}
+	wantSummaries := []CveContentStr{{Trivy, "Trivy summary"}, {Fortinet, "Fortinet summary"}, {Nvd, "NVD summary"}, {GitHub, "GitHub summary"}}
+	if got := vuln.Summaries("en", "pseudo"); !reflect.DeepEqual(got, wantSummaries) {
+		t.Errorf("Summaries() = %v, want %v", got, wantSummaries)
+	}
+	wantTitles := []CveContentStr{{Trivy, "Trivy summary"}, {Fortinet, "Fortinet title"}, {Nvd, "NVD summary"}}
+	if got := vuln.Titles("en", "pseudo"); len(got) < 3 || !reflect.DeepEqual(got[:3], wantTitles) {
+		t.Errorf("Titles() = %v, want prefix %v", got, wantTitles)
+	}
+	titleOnly := VulnInfo{CveContents: CveContents{Fortinet: {{Type: Fortinet, Title: "Title only"}}}}
+	if got := titleOnly.Summaries("en", "pseudo"); !reflect.DeepEqual(got, []CveContentStr{{Fortinet, "Title only"}}) {
+		t.Errorf("Summaries() for title-only advisory = %v", got)
+	}
+	scores := vuln.Cvss3Scores()
+	if len(scores) != 2 || scores[0].Type != Fortinet || scores[1].Type != Nvd {
+		t.Errorf("Cvss3Scores() = %v", scores)
+	}
+	urls := vuln.CveContents.PrimarySrcURLs("en", "pseudo", vuln.CveID, nil)
+	if len(urls) == 0 || urls[0] != (CveContentStr{Fortinet, "https://fortiguard.com/advisory"}) {
+		t.Errorf("PrimarySrcURLs() = %v", urls)
+	}
+}
